"""Limit unusually long silence generated by the speech model."""
import numpy as np


def limit_silence(samples, sample_rate):
    audio = np.asarray(samples, dtype=np.float32).reshape(-1)
    if not len(audio) or not np.isfinite(audio).all() or np.max(np.abs(audio)) < 1e-7:
        raise ValueError('O modelo gerou um trecho sem áudio audível. Tente gerar novamente.')
    # A relative, low threshold preserves quiet speech while identifying silent
    # frames. Only gaps of at least 1.5 s are shortened.
    frame = max(1, int(sample_rate * .02))
    threshold = max(1e-7, float(np.max(np.abs(audio))) * .003)
    count = (len(audio) + frame - 1) // frame
    padded = np.pad(audio, (0, count * frame - len(audio)))
    rms = np.sqrt(np.mean(padded.reshape(count, frame).astype(np.float64) ** 2, axis=1))
    silent = rms < threshold
    boundaries = np.flatnonzero(np.diff(np.r_[False, silent, False]))
    parts = []
    position = 0
    for first, last in zip(boundaries[::2], boundaries[1::2]):
        start, end = first * frame, min(last * frame, len(audio))
        if end - start < sample_rate * 1.5:
            continue
        parts.append(audio[position:start])
        keep = int(sample_rate * (.3 if start == 0 or end == len(audio) else .6))
        left = keep // 2
        parts.extend((audio[start:start + left], audio[end - (keep - left):end]))
        position = end
    parts.append(audio[position:])
    return np.concatenate(parts)
